-- V1.8.3 — Un groupe qui se retrouve (docs/V183_GROUPE_CORDEE.md). Applies after 20261125090000 (V1.8.2, la reprise du relais).
-- A group that finished a Cordée proposes a new private route and sets off again with the members who accept. Everything is the Cordée:
-- the new climb is an ordinary cordée (titan_challenges kind 'cordee'), its members are challenge members, its counts are the Cordée's.
--   * WHO: the group of a finished cordée is its members still roped in at the end (status 'joined'). A member who left (or was cut by a
--     block of the creator, which already marks them 'left') is not part of it any more. Proposals are possible during the 14 days after
--     the end (the window in which titan_cordees_v1 still lists the finished cordée).
--   * PROPOSE: a member chooses a route among the four existing ones, a pace among the three tested ones (douce, régulière, soutenue) and
--     a duration (7, 14, 21 or 28 days). The proposer accepts by proposing. The proposal lasts 72 hours (never past the 14-day window).
--     Nobody is invited outside the group, nobody is added without an answer; a free text is never asked.
--   * ANSWER: each other member of the group answers « accept » or « decline ». A member blocked with the proposer, or suspended, cannot
--     answer and is never added; a member's acceptance stops counting the moment they block or are blocked by the proposer.
--   * START: once two members have accepted (the proposer and one other), the new cordée starts NOW with counters at zero: a new row,
--     starts_at = now(), so only confirmed sessions recorded after the start count (the Cordée rule). Members who accepted are roped in;
--     members who have not answered yet are invited (they can still s'encorder or décliner, as any invitation); members who declined are
--     not added. The group forms as each one accepts: accepting a started proposal ropes one in at once (members cap 10 unchanged).
--   * TWO PROPOSALS AT ONCE: every action locks the finished cordée's row. The same route, pace and duration proposed twice give ONE
--     canonical proposal (the second proposer simply accepts it, « canonical: true »). Distinct proposals coexist (3 open at most) and each
--     member chooses explicitly: a member accepts one proposal at a time (accepting another one moves the acceptance), a proposer who
--     accepts another proposal rallies it (their own proposal becomes « merged »), a member already roped in a started proposal must
--     leave it before choosing another one.
--   * THE FINISHED CORDÉE stays closed and readable: nothing is reopened, nothing is moved; the new cordée names it (« follows ») and the
--     finished cordée tells its story (« story »): only shareable steps (formed, relay opened and received, camps, summit or end) and the
--     group's decisions (proposals, counts of acceptances and refusals, the departure of the new cordée). Never a session, a sport, a
--     date of training, a duration or a distance; names under the Cordée naming rule only; a refusal is a count, never a name.
--   * VISIBILITY: link partners of a cordée keep seeing each other in the cordées that follow it (private.titan_member_named now follows the
--     chain of proposals), blocks still hide; nobody else is named. Departures, blocks and suspensions apply to the new cordée as to any.
--   * « DEPUIS TA DERNIÈRE VISITE »: titan_social_digest_v1 adds « suites » (a proposal waits for my answer, two proposals to choose from,
--     my proposal's acceptances) and « follows » on each cordée; no notification is sent.
--   * NO FREE ADVANCE: proposing, accepting or starting adds no longueur, XP, credit or title; the old counts never carry over.
--   * LIMITS: one open proposal per proposer and finished cordée, 3 open proposals per finished cordée, the creation limits of the Cordée
--     for the proposer (3 cordées created a day through titan_social_rate_limit 'cordee_create', 3 running cordées including open proposals).
--   * Opens with the server flag screens.cordee_suite (absent = closed, per-account rollout), checked here for propose and answers, with
--     screens.cordee for proposing. Withdrawing one's own proposal is always possible.
--   * Export: « cordeeSuites » (one's own proposals and answers, never another member's) is added to private.titan_social_export_v1.
--     Erasure: a proposal keeps the group's history with no person (on delete set null); an erased member's answers go with the account.
--   * Measure: private.titan_cordee_suite_measure(since) (service role): groups that finished a cordée and became active together within
--     14 days, their size and their first participation. Counts only.
-- Additive. The caller owns the transaction: never BEGIN/COMMIT here.
-- Rollback: drop function public.titan_cordee_suite_v1(uuid, text, uuid, text, text, integer), private.titan_cordee_suite_measure(timestamptz),
-- private.titan_cordee_suite_state(uuid, uuid), private.titan_cordee_story(uuid, uuid), private.titan_cordee_follows(uuid, uuid),
-- private.titan_cordee_suite_start(uuid), private.titan_cordee_suite_tidy(uuid), private.titan_cordee_suite_can_answer(uuid, uuid),
-- private.titan_cordee_suite_yes(uuid), trigger titan_challenge_members_suite and function private.titan_challenge_members_suite();
-- re-apply private.titan_member_named from 20261120100000, public.titan_cordees_v1 and private.titan_social_export_v1 from 20261125090000,
-- public.titan_social_digest_v1 from 20261120120000; drop tables private.titan_cordee_suite_answers, private.titan_cordee_suites.

-- ---------------------------------------------------------------------------------------------
-- 1. Proposals and answers.
-- ---------------------------------------------------------------------------------------------
create table if not exists private.titan_cordee_suites (
  id uuid primary key default gen_random_uuid(),
  from_id uuid not null references public.titan_challenges(id) on delete cascade,
  proposed_by uuid references auth.users(id) on delete set null,
  route text not null check (route in ('aube', 'marees', 'forge', 'aurores')),
  pace text not null check (pace in ('douce', 'reguliere', 'soutenue')),
  days integer not null check (days in (7, 14, 21, 28)),
  status text not null default 'open' check (status in ('open', 'started', 'withdrawn', 'merged', 'expired', 'cancelled')),
  created_at timestamptz not null default clock_timestamp(),
  expires_at timestamptz not null,
  -- Deferred: erasing a proposer who created the started cordée clears both references in one statement.
  started_id uuid references public.titan_challenges(id) on delete set null deferrable initially deferred,
  started_at timestamptz,
  resolved_at timestamptz,
  check ((status = 'started') = (started_at is not null)),
  check (expires_at > created_at)
);
-- One canonical open proposal per route, pace and duration; one open proposal per proposer.
create unique index if not exists titan_cordee_suites_canonical_idx on private.titan_cordee_suites (from_id, route, pace, days) where status = 'open';
create unique index if not exists titan_cordee_suites_proposer_idx on private.titan_cordee_suites (from_id, proposed_by) where status = 'open';
create index if not exists titan_cordee_suites_from_idx on private.titan_cordee_suites (from_id, created_at);
create index if not exists titan_cordee_suites_started_idx on private.titan_cordee_suites (started_id);
create index if not exists titan_cordee_suites_by_idx on private.titan_cordee_suites (proposed_by);
alter table private.titan_cordee_suites enable row level security;
revoke all on private.titan_cordee_suites from public, anon, authenticated;

create table if not exists private.titan_cordee_suite_answers (
  suite_id uuid not null references private.titan_cordee_suites(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  answer text not null check (answer in ('yes', 'no')),
  answered_at timestamptz not null default clock_timestamp(),
  primary key (suite_id, user_id)
);
create index if not exists titan_cordee_suite_answers_user_idx on private.titan_cordee_suite_answers (user_id);
alter table private.titan_cordee_suite_answers enable row level security;
revoke all on private.titan_cordee_suite_answers from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- 2. Who may answer, who accepted (pure reads: a departure, a block or a suspension counts at once).
-- ---------------------------------------------------------------------------------------------
-- A member of the finished group who may answer this proposal: still roped in the finished cordée, not suspended, no block with the proposer.
create or replace function private.titan_cordee_suite_can_answer(p_suite uuid, p_user uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select p_user is not null and exists (
    select 1 from private.titan_cordee_suites s
      join public.titan_challenge_members m on m.challenge_id = s.from_id and m.user_id = p_user and m.status = 'joined'
     where s.id = p_suite
       and not exists (select 1 from public.profiles p where p.id = p_user and coalesce(p.is_suspended, false))
       and (s.proposed_by is null or s.proposed_by = p_user or not exists (select 1 from public.titan_user_blocks k
             where (k.blocker_id = p_user and k.blocked_id = s.proposed_by) or (k.blocker_id = s.proposed_by and k.blocked_id = p_user))));
$$;
revoke all on function private.titan_cordee_suite_can_answer(uuid, uuid) from public, anon, authenticated;

-- The acceptances that count now (members who may still answer).
create or replace function private.titan_cordee_suite_yes(p_suite uuid)
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
  select a.user_id from private.titan_cordee_suite_answers a
   where a.suite_id = p_suite and a.answer = 'yes' and private.titan_cordee_suite_can_answer(p_suite, a.user_id);
$$;
revoke all on function private.titan_cordee_suite_yes(uuid) from public, anon, authenticated;

-- Open proposals that can no longer stand are closed: expired, or whose proposer left the group, was suspended or erased.
create or replace function private.titan_cordee_suite_tidy(p_from uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $function$
begin
  update private.titan_cordee_suites s set status = 'expired', resolved_at = now()
   where s.from_id = p_from and s.status = 'open' and s.expires_at <= now();
  update private.titan_cordee_suites s set status = 'cancelled', resolved_at = now()
   where s.from_id = p_from and s.status = 'open' and (s.proposed_by is null or not private.titan_cordee_suite_can_answer(s.id, s.proposed_by));
end;
$function$;
revoke all on function private.titan_cordee_suite_tidy(uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- 3. Visibility: link partners of a cordée keep seeing each other in the cordées that follow it (blocks still hide).
--    From 20261120100000, one change: the invitation links of the cordées this one follows count too (8 steps back at most).
-- ---------------------------------------------------------------------------------------------
create or replace function private.titan_member_named(p_viewer uuid, p_member uuid, p_challenge uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select p_member = p_viewer or private.titan_are_friends(p_viewer, p_member) or (
    exists (
      with recursive chain(id, depth) as (
        select p_challenge, 0
        union all
        select s.from_id, chain.depth + 1 from private.titan_cordee_suites s join chain on s.started_id = chain.id where chain.depth < 8)
      select 1 from private.titan_challenge_invites i
       where i.challenge_id in (select chain.id from chain) and i.used_at is not null
         and ((i.created_by = p_viewer and i.used_by = p_member) or (i.created_by = p_member and i.used_by = p_viewer)))
    and not exists (select 1 from public.titan_user_blocks k
                     where (k.blocker_id = p_viewer and k.blocked_id = p_member) or (k.blocker_id = p_member and k.blocked_id = p_viewer)));
$$;
revoke all on function private.titan_member_named(uuid, uuid, uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- 4. Starting a proposal: a new cordée, counters at zero, with the members who accepted.
-- ---------------------------------------------------------------------------------------------
create or replace function private.titan_cordee_suite_start(p_suite uuid)
returns uuid
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_s private.titan_cordee_suites%rowtype;
  v_id uuid;
  v_title text;
begin
  select * into v_s from private.titan_cordee_suites where id = p_suite for update;
  if v_s.status <> 'open' or v_s.expires_at <= now() then return null; end if;
  if (select count(*) from private.titan_cordee_suite_yes(p_suite)) < 2 then return null; end if;
  if v_s.proposed_by is null or not private.titan_cordee_suite_can_answer(p_suite, v_s.proposed_by) then return null; end if;
  v_title := case v_s.route when 'aube' then 'Les crêtes de l’Aube' when 'marees' then 'La passe des Marées'
                            when 'forge' then 'Les cols d’Obsidienne' else 'La voûte des Aurores' end;
  -- A new row: starts now, ends after the chosen duration; the old counts never carry over (sessions recorded after the start only).
  insert into public.titan_challenges(creator_id, title, metric, sport, target, starts_at, ends_at, kind, route, pace)
  values (v_s.proposed_by, v_title, 'pitches', null, private.titan_cordee_share(v_s.pace, v_s.days), now(), now() + make_interval(days => v_s.days),
          'cordee', v_s.route, v_s.pace)
  returning id into v_id;
  update private.titan_cordee_suites set status = 'started', started_id = v_id, started_at = now(), resolved_at = now() where id = p_suite;
  -- Those who accepted are roped in (the proposer first, as the creator)…
  insert into public.titan_challenge_members(challenge_id, user_id, status, joined_at)
  select v_id, y, 'joined', now() from private.titan_cordee_suite_yes(p_suite) y
   order by (y = v_s.proposed_by) desc
  on conflict do nothing;
  -- …those who have not answered yet are invited (they can still s'encorder or décliner); those who declined are not added.
  insert into public.titan_challenge_members(challenge_id, user_id, status)
  select v_id, m.user_id, 'invited' from public.titan_challenge_members m
   where m.challenge_id = v_s.from_id and m.status = 'joined'
     and not exists (select 1 from private.titan_cordee_suite_answers a where a.suite_id = p_suite and a.user_id = m.user_id)
     and private.titan_cordee_suite_can_answer(p_suite, m.user_id)
  on conflict do nothing;
  return v_id;
end;
$function$;
revoke all on function private.titan_cordee_suite_start(uuid) from public, anon, authenticated;

-- The answers follow the new cordée: s'encorder there is accepting (and chooses it over the other open proposals), décliner is refusing.
create or replace function private.titan_challenge_members_suite()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_s private.titan_cordee_suites%rowtype;
begin
  if tg_op = 'UPDATE' and new.status is not distinct from old.status then return null; end if;
  select * into v_s from private.titan_cordee_suites where started_id = new.challenge_id;
  if not found then return null; end if;
  if new.status = 'joined' then
    insert into private.titan_cordee_suite_answers (suite_id, user_id, answer) values (v_s.id, new.user_id, 'yes')
    on conflict (suite_id, user_id) do update set answer = 'yes', answered_at = clock_timestamp() where private.titan_cordee_suite_answers.answer <> 'yes';
    delete from private.titan_cordee_suite_answers a using private.titan_cordee_suites o
     where a.suite_id = o.id and o.from_id = v_s.from_id and o.id <> v_s.id and o.status = 'open' and a.user_id = new.user_id and a.answer = 'yes';
    update private.titan_cordee_suites o set status = 'merged', resolved_at = now()
     where o.from_id = v_s.from_id and o.id <> v_s.id and o.status = 'open' and o.proposed_by = new.user_id;
  elsif new.status = 'declined' then
    insert into private.titan_cordee_suite_answers (suite_id, user_id, answer) values (v_s.id, new.user_id, 'no')
    on conflict (suite_id, user_id) do update set answer = 'no', answered_at = clock_timestamp();
  end if;
  return null;
end;
$function$;
revoke all on function private.titan_challenge_members_suite() from public, anon, authenticated;
drop trigger if exists titan_challenge_members_suite on public.titan_challenge_members;
create trigger titan_challenge_members_suite after insert or update of status on public.titan_challenge_members
  for each row execute function private.titan_challenge_members_suite();

-- ---------------------------------------------------------------------------------------------
-- 5. What one member reads: the story of a finished cordée, the proposals to set off again, the cordée a new one follows.
-- ---------------------------------------------------------------------------------------------
-- A person under the Cordée naming rule of the finished cordée (oneself, friends, link partners, never across a block).
create or replace function private.titan_cordee_suite_person(p_from uuid, p_viewer uuid, p_member uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select case when p_member is not null and private.titan_member_named(p_viewer, p_member, p_from)
    then jsonb_build_object('name', coalesce(nullif((select p.username from public.profiles p where p.id = p_member), ''), 'Athlète'), 'me', p_member = p_viewer)
    else jsonb_build_object('name', 'Membre de la cordée', 'me', false) end;
$$;
revoke all on function private.titan_cordee_suite_person(uuid, uuid, uuid) from public, anon, authenticated;

-- The proposals of a finished cordée as one member sees them, and what this member can do. null when the viewer is not of the group.
create or replace function private.titan_cordee_suite_state(p_from uuid, p_viewer uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  v_c public.titan_challenges%rowtype;
  v_closes timestamptz;
  v_open integer;
  v_mine_open boolean;
  v_in uuid;
  v_others integer;
  v_list jsonb := '[]'::jsonb;
  v_can jsonb := '[]'::jsonb;
  v_waiting integer := 0;
  v_suspended boolean;
  sg record;
  v_eligible integer; v_yes integer; v_no integer; v_my text; v_accepted jsonb; v_turn jsonb; v_status text; v_new text;
  v_hidden integer;
begin
  select * into v_c from public.titan_challenges where id = p_from and kind = 'cordee';
  if not found or (v_c.summited_at is null and now() <= v_c.ends_at) then return null; end if;
  if not exists (select 1 from public.titan_challenge_members m where m.challenge_id = p_from and m.user_id = p_viewer and m.status = 'joined') then
    return null;
  end if;
  v_suspended := exists (select 1 from public.profiles p where p.id = p_viewer and coalesce(p.is_suspended, false));
  v_closes := v_c.ends_at + interval '14 days';
  select count(*)::integer into v_open from private.titan_cordee_suites s where s.from_id = p_from and s.status = 'open' and s.expires_at > now();
  v_mine_open := exists (select 1 from private.titan_cordee_suites s where s.from_id = p_from and s.status = 'open' and s.expires_at > now() and s.proposed_by = p_viewer);
  -- The started proposal I am roped in (still running): I must leave it before choosing another one.
  select s.started_id into v_in from private.titan_cordee_suites s
    join public.titan_challenge_members m on m.challenge_id = s.started_id and m.user_id = p_viewer and m.status = 'joined'
    join public.titan_challenges n on n.id = s.started_id and n.summited_at is null and n.ends_at > now()
   where s.from_id = p_from and s.status = 'started' limit 1;
  select count(*)::integer into v_others from public.titan_challenge_members m
   where m.challenge_id = p_from and m.status = 'joined' and m.user_id <> p_viewer
     and not exists (select 1 from public.profiles p where p.id = m.user_id and coalesce(p.is_suspended, false))
     and not exists (select 1 from public.titan_user_blocks k where (k.blocker_id = p_viewer and k.blocked_id = m.user_id) or (k.blocker_id = m.user_id and k.blocked_id = p_viewer));
  for sg in select * from private.titan_cordee_suites x where x.from_id = p_from order by x.created_at loop
    v_status := case when sg.status = 'open' and sg.expires_at <= now() then 'expired'
                     when sg.status = 'open' and (sg.proposed_by is null or not private.titan_cordee_suite_can_answer(sg.id, sg.proposed_by)) then 'cancelled'
                     else sg.status end;
    -- A proposal of someone I am blocked with is not mine to answer: it is not listed (the story keeps it as a nameless decision).
    if sg.proposed_by is not null and sg.proposed_by <> p_viewer and exists (select 1 from public.titan_user_blocks k
         where (k.blocker_id = p_viewer and k.blocked_id = sg.proposed_by) or (k.blocker_id = sg.proposed_by and k.blocked_id = p_viewer)) then
      continue;
    end if;
    select count(*)::integer into v_eligible from public.titan_challenge_members m
     where m.challenge_id = p_from and m.status = 'joined' and private.titan_cordee_suite_can_answer(sg.id, m.user_id);
    if v_status = 'open' then
      select count(*)::integer into v_yes from private.titan_cordee_suite_yes(sg.id);
    else
      select count(*)::integer into v_yes from private.titan_cordee_suite_answers a where a.suite_id = sg.id and a.answer = 'yes';
    end if;
    select count(*)::integer into v_no from private.titan_cordee_suite_answers a where a.suite_id = sg.id and a.answer = 'no';
    select a.answer into v_my from private.titan_cordee_suite_answers a where a.suite_id = sg.id and a.user_id = p_viewer;
    -- Who accepted, under the naming rule; the others who accepted are a count. A refusal is never named.
    select coalesce(jsonb_agg(private.titan_cordee_suite_person(p_from, p_viewer, a.user_id) order by a.answered_at)
             filter (where a.user_id = p_viewer or private.titan_member_named(p_viewer, a.user_id, p_from)), '[]'::jsonb),
           count(*) filter (where not (a.user_id = p_viewer or private.titan_member_named(p_viewer, a.user_id, p_from)))::integer
      into v_accepted, v_hidden
      from private.titan_cordee_suite_answers a where a.suite_id = sg.id and a.answer = 'yes'
       and (v_status <> 'open' or private.titan_cordee_suite_can_answer(sg.id, a.user_id));
    v_new := null;
    if v_status = 'started' then
      select m.status into v_new from public.titan_challenge_members m where m.challenge_id = sg.started_id and m.user_id = p_viewer;
    end if;
    v_turn := '[]'::jsonb;
    if not v_suspended then
      if v_status = 'open' and sg.proposed_by = p_viewer then
        v_turn := jsonb_build_array('withdraw');
      elsif v_status = 'open' and private.titan_cordee_suite_can_answer(sg.id, p_viewer) and v_in is null then
        v_turn := case when v_my = 'yes' then jsonb_build_array('decline') when v_my = 'no' then jsonb_build_array('accept')
                       else jsonb_build_array('accept', 'decline') end;
        if v_my is null then v_waiting := v_waiting + 1; end if;
      elsif v_status = 'started' and private.titan_cordee_suite_can_answer(sg.id, p_viewer)
            and exists (select 1 from public.titan_challenges n where n.id = sg.started_id and n.summited_at is null and n.ends_at > now())
            and (v_in is null or v_in = sg.started_id) then
        v_turn := case when v_new = 'invited' then jsonb_build_array('accept', 'decline')
                       when v_new is null or v_new = 'declined' then jsonb_build_array('accept') else '[]'::jsonb end;
        if v_new = 'invited' then v_waiting := v_waiting + 1; end if;
      end if;
    end if;
    v_list := v_list || jsonb_build_array(jsonb_build_object(
      'id', sg.id, 'route', sg.route, 'pace', sg.pace, 'days', sg.days, 'status', v_status,
      'by', private.titan_cordee_suite_person(p_from, p_viewer, sg.proposed_by), 'mine', sg.proposed_by = p_viewer,
      'myAnswer', case when v_new = 'joined' then 'yes' when v_new = 'declined' then 'no' else v_my end,
      'yes', v_yes, 'no', v_no, 'eligible', v_eligible, 'waiting', greatest(0, v_eligible - v_yes - v_no),
      'accepted', v_accepted, 'others', v_hidden,
      'expiresAt', case when v_status = 'open' then sg.expires_at end, 'createdAt', sg.created_at,
      'startedId', sg.started_id, 'startedAt', sg.started_at, 'myStatus', v_new,
      'joined', case when v_status = 'started' then (select count(*) from public.titan_challenge_members m where m.challenge_id = sg.started_id and m.status = 'joined') end,
      'turn', v_turn));
  end loop;
  if not v_suspended and now() < v_closes and v_in is null and not v_mine_open and v_open < 3 and v_others > 0 then
    v_can := jsonb_build_array('propose');
  end if;
  return jsonb_build_object(
    'closesAt', v_closes, 'can', v_can, 'group', v_others + 1, 'waiting', v_waiting,
    -- Two distinct open proposals or more: the group chooses explicitly (a member accepts one at a time).
    'choice', (select count(*) from jsonb_array_elements(v_list) x where x->>'status' = 'open') >= 2,
    'previous', jsonb_build_object('route', v_c.route, 'pace', v_c.pace,
      'days', greatest(1, round(extract(epoch from (v_c.ends_at - v_c.starts_at)) / 86400))::integer, 'summited', v_c.summited_at is not null),
    'proposals', v_list,
    'hint', case when v_suspended then 'suspended' when now() >= v_closes then 'closed' when v_in is not null then 'in'
                 when v_others = 0 then 'alone' when v_waiting > 0 then 'answer' when v_mine_open then 'mine' when v_open >= 3 then 'full'
                 else 'propose' end);
end;
$function$;
revoke all on function private.titan_cordee_suite_state(uuid, uuid) from public, anon, authenticated;

-- The cordée a running one follows: closed and readable from the new one (route, outcome, figures of the group, never a session).
create or replace function private.titan_cordee_follows(p_challenge uuid, p_viewer uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object('id', f.id, 'route', f.route, 'pace', f.pace, 'summited', f.summited_at is not null, 'endedAt', f.ends_at,
           'proposedBy', private.titan_cordee_suite_person(f.id, p_viewer, s.proposed_by),
           'group', (select count(*) from public.titan_challenge_members m where m.challenge_id = f.id and m.status = 'joined'),
           'camps', (st->>'camps')::integer, 'total', (st->>'total')::integer, 'target', (st->>'target')::integer)
    from private.titan_cordee_suites s
    join public.titan_challenges f on f.id = s.from_id
    cross join lateral (select private.titan_cordee_state(f.id, p_viewer) as st) x
   where s.started_id = p_challenge
   limit 1;
$$;
revoke all on function private.titan_cordee_follows(uuid, uuid) from public, anon, authenticated;

-- The story of a cordée: shareable steps and the group's decisions only, in order.
create or replace function private.titan_cordee_story(p_challenge uuid, p_viewer uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  v_c public.titan_challenges%rowtype;
  v_out jsonb := '[]'::jsonb;
  v_state jsonb;
  v_r record;
  v_f jsonb;
  sg record;
begin
  select * into v_c from public.titan_challenges where id = p_challenge and kind = 'cordee';
  if not found then return '[]'::jsonb; end if;
  v_state := private.titan_cordee_state(p_challenge, p_viewer);
  v_out := v_out || jsonb_build_array(jsonb_build_object('kind', 'formed', 'at', v_c.starts_at,
    'members', (select count(*) from public.titan_challenge_members m where m.challenge_id = p_challenge and (m.status = 'joined' or (m.status = 'left' and m.joined_at is not null)))));
  v_f := private.titan_cordee_follows(p_challenge, p_viewer);
  if v_f is not null then
    v_out := v_out || jsonb_build_array(jsonb_build_object('kind', 'follows', 'at', v_c.starts_at, 'route', v_f->>'route', 'summited', (v_f->>'summited')::boolean));
  end if;
  if to_regclass('private.titan_cordee_relays') is not null then
    select * into v_r from private.titan_cordee_relays r where r.challenge_id = p_challenge;
    if found then
      v_out := v_out || jsonb_build_array(jsonb_build_object('kind', 'relay_opened', 'at', v_r.opened_at,
        'who', private.titan_cordee_relay_person(p_challenge, p_viewer, v_r.opened_by, v_r.opened_family)));
      if v_r.confirmed_at is not null then
        v_out := v_out || jsonb_build_array(jsonb_build_object('kind', 'relay_confirmed', 'at', v_r.confirmed_at,
          'who', private.titan_cordee_relay_person(p_challenge, p_viewer, v_r.confirmed_by, v_r.confirmed_family)));
      end if;
    end if;
  end if;
  if (v_state->>'camps')::integer > 0 then
    v_out := v_out || jsonb_build_array(jsonb_build_object('kind', 'camps', 'camps', (v_state->>'camps')::integer,
      'total', (v_state->>'total')::integer, 'target', (v_state->>'target')::integer));
  end if;
  if v_c.summited_at is not null then
    v_out := v_out || jsonb_build_array(jsonb_build_object('kind', 'summit', 'at', v_c.summited_at, 'total', (v_state->>'total')::integer));
  elsif now() > v_c.ends_at then
    v_out := v_out || jsonb_build_array(jsonb_build_object('kind', 'ended', 'at', v_c.ends_at, 'total', (v_state->>'total')::integer, 'target', (v_state->>'target')::integer));
  end if;
  -- The group's decisions: each proposal (by whom under the naming rule, how many accepted and declined) and each departure together.
  for sg in select x.* from private.titan_cordee_suites x where x.from_id = p_challenge order by x.created_at loop
    v_out := v_out || jsonb_build_array(jsonb_build_object('kind', 'proposal', 'at', sg.created_at, 'route', sg.route, 'pace', sg.pace, 'days', sg.days,
      'by', private.titan_cordee_suite_person(p_challenge, p_viewer, sg.proposed_by),
      'status', case when sg.status = 'open' and sg.expires_at <= now() then 'expired' else sg.status end,
      'yes', (select count(*) from private.titan_cordee_suite_answers a where a.suite_id = sg.id and a.answer = 'yes'),
      'no', (select count(*) from private.titan_cordee_suite_answers a where a.suite_id = sg.id and a.answer = 'no')));
    if sg.status = 'started' then
      v_out := v_out || jsonb_build_array(jsonb_build_object('kind', 'suite', 'at', sg.started_at, 'route', sg.route, 'pace', sg.pace,
        'joined', (select count(*) from public.titan_challenge_members m where m.challenge_id = sg.started_id and m.status = 'joined')));
    end if;
  end loop;
  return v_out;
end;
$function$;
revoke all on function private.titan_cordee_story(uuid, uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- 6. Propose, accept, decline, withdraw. The finished cordée's row is locked: one canonical proposal, one start.
-- ---------------------------------------------------------------------------------------------
create or replace function public.titan_cordee_suite_v1(p_from uuid, p_action text, p_suite uuid default null,
  p_route text default null, p_pace text default null, p_days integer default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
set statement_timeout = '8s'
as $function$
declare
  v_uid uuid := auth.uid();
  v_c public.titan_challenges%rowtype;
  v_s private.titan_cordee_suites%rowtype;
  v_n public.titan_challenges%rowtype;
  v_status text;
  v_changed boolean := false;
  v_canonical boolean := false;
  v_started uuid;
  v_in uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode = '42501'; end if;
  if exists (select 1 from public.profiles where id = v_uid and coalesce(is_suspended, false)) then raise exception 'ACCOUNT_SUSPENDED' using errcode = '42501'; end if;
  if p_from is null or p_action is null or p_action not in ('propose', 'accept', 'decline', 'withdraw') then raise exception 'SUITE_INVALID' using errcode = '22023'; end if;
  -- Withdrawing one's own proposal always works; the rest opens with the flag (and proposing with the Cordée's own flag).
  if p_action <> 'withdraw' and not private.titan_flag_on('screens.cordee_suite') then raise exception 'FEATURE_DISABLED' using errcode = '42501'; end if;
  if p_action = 'propose' and not private.titan_flag_on('screens.cordee') then raise exception 'FEATURE_DISABLED' using errcode = '42501'; end if;
  if not exists (select 1 from public.titan_challenge_members m join public.titan_challenges c on c.id = m.challenge_id
                  where m.challenge_id = p_from and m.user_id = v_uid and m.status = 'joined' and c.kind = 'cordee') then
    raise exception 'CHALLENGE_NOT_FOUND' using errcode = 'P0002';
  end if;
  perform private.titan_cordee_settle(p_from);
  select * into v_c from public.titan_challenges where id = p_from for update;
  if v_c.summited_at is null and now() <= v_c.ends_at then raise exception 'SUITE_NOT_FINISHED' using errcode = '22023'; end if;
  perform private.titan_cordee_suite_tidy(p_from);
  -- The started proposal I am roped in, still running.
  select s.started_id into v_in from private.titan_cordee_suites s
    join public.titan_challenge_members m on m.challenge_id = s.started_id and m.user_id = v_uid and m.status = 'joined'
    join public.titan_challenges n on n.id = s.started_id and n.summited_at is null and n.ends_at > now()
   where s.from_id = p_from and s.status = 'started' limit 1;

  if p_action = 'propose' then
    if now() >= v_c.ends_at + interval '14 days' then raise exception 'SUITE_CLOSED' using errcode = '22023'; end if;
    if p_route is null or p_route not in ('aube', 'marees', 'forge', 'aurores') or p_pace is null or p_pace not in ('douce', 'reguliere', 'soutenue')
       or p_days is null or p_days not in (7, 14, 21, 28) then
      raise exception 'CORDEE_INVALID' using errcode = '22023';
    end if;
    if v_in is not null then raise exception 'SUITE_ALREADY_IN' using errcode = '22023'; end if;
    -- The same route, pace and duration already proposed: that is the canonical proposal, proposing it again accepts it.
    select * into v_s from private.titan_cordee_suites s where s.from_id = p_from and s.status = 'open'
       and s.route = p_route and s.pace = p_pace and s.days = p_days;
    if found then
      v_canonical := true;
      if v_s.proposed_by = v_uid then
        null; -- my own proposal again: nothing changes
      elsif not private.titan_cordee_suite_can_answer(v_s.id, v_uid) then
        raise exception 'SUITE_UNAVAILABLE' using errcode = '22023';
      else
        p_action := 'accept';
        p_suite := v_s.id;
      end if;
    else
      if exists (select 1 from private.titan_cordee_suites s where s.from_id = p_from and s.status = 'open' and s.proposed_by = v_uid) then
        raise exception 'SUITE_PENDING' using errcode = '22023';
      end if;
      if (select count(*) from private.titan_cordee_suites s where s.from_id = p_from and s.status = 'open') >= 3 then
        raise exception 'SUITE_LIMIT' using errcode = '22023';
      end if;
      if not exists (select 1 from public.titan_challenge_members m where m.challenge_id = p_from and m.status = 'joined' and m.user_id <> v_uid
                       and not exists (select 1 from public.profiles p where p.id = m.user_id and coalesce(p.is_suspended, false))
                       and not exists (select 1 from public.titan_user_blocks k where (k.blocker_id = v_uid and k.blocked_id = m.user_id) or (k.blocker_id = m.user_id and k.blocked_id = v_uid))) then
        raise exception 'SUITE_GROUP_TOO_SMALL' using errcode = '22023';
      end if;
      -- The Cordée's creation limits: the limiter first (it serialises this account), then running cordées and open proposals.
      perform public.titan_social_rate_limit(v_uid, 'cordee_create', interval '1 day', 3);
      if (select count(*) from public.titan_challenges c where c.creator_id = v_uid and c.kind = 'cordee' and c.ends_at > now() and c.summited_at is null)
         + (select count(*) from private.titan_cordee_suites s where s.proposed_by = v_uid and s.status = 'open' and s.expires_at > now()) >= 3 then
        raise exception 'CORDEE_LIMIT_3' using errcode = '22023';
      end if;
      insert into private.titan_cordee_suites (from_id, proposed_by, route, pace, days, expires_at)
      values (p_from, v_uid, p_route, p_pace, p_days, least(v_c.ends_at + interval '14 days', clock_timestamp() + interval '72 hours'))
      returning * into v_s;
      -- Proposing is choosing: my acceptance of another open proposal moves to mine.
      delete from private.titan_cordee_suite_answers a using private.titan_cordee_suites o
       where a.suite_id = o.id and o.from_id = p_from and o.id <> v_s.id and o.status = 'open' and a.user_id = v_uid and a.answer = 'yes';
      insert into private.titan_cordee_suite_answers (suite_id, user_id, answer) values (v_s.id, v_uid, 'yes');
      v_changed := true;
    end if;
  end if;

  if p_action in ('accept', 'decline', 'withdraw') and v_s.id is null then
    select * into v_s from private.titan_cordee_suites s where s.id = p_suite and s.from_id = p_from;
    if not found then raise exception 'SUITE_NOT_FOUND' using errcode = 'P0002'; end if;
  end if;
  v_status := v_s.status;

  if p_action = 'withdraw' then
    if v_s.proposed_by is distinct from v_uid then raise exception 'SUITE_NOT_MINE' using errcode = '22023'; end if;
    if v_status = 'open' then
      update private.titan_cordee_suites set status = 'withdrawn', resolved_at = now() where id = v_s.id;
      v_changed := true;
    elsif v_status <> 'withdrawn' then
      raise exception 'SUITE_CLOSED' using errcode = '22023';
    end if;

  elsif p_action = 'accept' then
    if not private.titan_cordee_suite_can_answer(v_s.id, v_uid) then raise exception 'SUITE_UNAVAILABLE' using errcode = '22023'; end if;
    if v_status = 'open' then
      if v_in is not null then raise exception 'SUITE_ALREADY_IN' using errcode = '22023'; end if;
      if not exists (select 1 from private.titan_cordee_suite_answers a where a.suite_id = v_s.id and a.user_id = v_uid and a.answer = 'yes') then
        insert into private.titan_cordee_suite_answers (suite_id, user_id, answer) values (v_s.id, v_uid, 'yes')
        on conflict (suite_id, user_id) do update set answer = 'yes', answered_at = clock_timestamp();
        -- One acceptance at a time: choosing this proposal moves my acceptance away from the others; mine, if any, rallies this one.
        delete from private.titan_cordee_suite_answers a using private.titan_cordee_suites o
         where a.suite_id = o.id and o.from_id = p_from and o.id <> v_s.id and o.status = 'open' and a.user_id = v_uid and a.answer = 'yes';
        update private.titan_cordee_suites o set status = 'merged', resolved_at = now()
         where o.from_id = p_from and o.id <> v_s.id and o.status = 'open' and o.proposed_by = v_uid;
        v_changed := true;
      end if;
      v_started := private.titan_cordee_suite_start(v_s.id);
    elsif v_status = 'started' then
      -- The group already set off: accepting ropes me in at once (the members cap of the Cordée holds).
      if v_in is not null and v_in <> v_s.started_id then raise exception 'SUITE_ALREADY_IN' using errcode = '22023'; end if;
      select * into v_n from public.titan_challenges where id = v_s.started_id for update;
      if v_n.id is null or v_n.summited_at is not null or now() > v_n.ends_at then raise exception 'SUITE_CLOSED' using errcode = '22023'; end if;
      if exists (select 1 from public.titan_challenge_members m where m.challenge_id = v_n.id and m.user_id = v_uid and m.status = 'joined') then
        null; -- already roped in: nothing changes
      else
        if (select count(*) from public.titan_challenge_members m where m.challenge_id = v_n.id and m.status = 'joined') >= 10 then
          raise exception 'SUITE_FULL' using errcode = '22023';
        end if;
        insert into public.titan_challenge_members (challenge_id, user_id, status, joined_at) values (v_n.id, v_uid, 'joined', now())
        on conflict (challenge_id, user_id) do update set status = 'joined', joined_at = now();
        v_changed := true;
      end if;
    else
      raise exception 'SUITE_CLOSED' using errcode = '22023';
    end if;

  elsif p_action = 'decline' then
    if v_s.proposed_by = v_uid then raise exception 'SUITE_OWN' using errcode = '22023'; end if;
    if not private.titan_cordee_suite_can_answer(v_s.id, v_uid) then raise exception 'SUITE_UNAVAILABLE' using errcode = '22023'; end if;
    if v_status = 'open' then
      if not exists (select 1 from private.titan_cordee_suite_answers a where a.suite_id = v_s.id and a.user_id = v_uid and a.answer = 'no') then
        insert into private.titan_cordee_suite_answers (suite_id, user_id, answer) values (v_s.id, v_uid, 'no')
        on conflict (suite_id, user_id) do update set answer = 'no', answered_at = clock_timestamp();
        v_changed := true;
      end if;
    elsif v_status = 'started' then
      if exists (select 1 from public.titan_challenge_members m where m.challenge_id = v_s.started_id and m.user_id = v_uid and m.status = 'joined') then
        raise exception 'SUITE_ALREADY_IN' using errcode = '22023';
      end if;
      update public.titan_challenge_members set status = 'declined' where challenge_id = v_s.started_id and user_id = v_uid and status = 'invited';
      if found then v_changed := true;
      elsif not exists (select 1 from private.titan_cordee_suite_answers a where a.suite_id = v_s.id and a.user_id = v_uid and a.answer = 'no') then
        insert into private.titan_cordee_suite_answers (suite_id, user_id, answer) values (v_s.id, v_uid, 'no')
        on conflict (suite_id, user_id) do update set answer = 'no', answered_at = clock_timestamp();
        v_changed := true;
      end if;
    else
      raise exception 'SUITE_CLOSED' using errcode = '22023';
    end if;
  end if;

  select status, started_id into v_status, v_started from private.titan_cordee_suites where id = v_s.id;
  return jsonb_build_object('suite', private.titan_cordee_suite_state(p_from, v_uid), 'proposal', v_s.id, 'status', v_status,
    'started', v_started, 'canonical', v_canonical, 'changed', v_changed);
end;
$function$;
revoke all on function public.titan_cordee_suite_v1(uuid, text, uuid, text, text, integer) from public, anon;
grant execute on function public.titan_cordee_suite_v1(uuid, text, uuid, text, text, integer) to authenticated;

-- ---------------------------------------------------------------------------------------------
-- 7. My cordées (from 20261125090000): open proposals are tidied; a finished cordée carries its story and its proposals, a new one the
--    cordée it follows.
-- ---------------------------------------------------------------------------------------------
create or replace function public.titan_cordees_v1()
returns jsonb
language plpgsql
security definer
set search_path = ''
set statement_timeout = '8s'
as $function$
declare
  v_uid uuid := auth.uid();
  v_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode = '42501'; end if;
  for v_id in select c.id from public.titan_challenges c join public.titan_challenge_members m on m.challenge_id = c.id and m.user_id = v_uid
               where c.kind = 'cordee' and c.summited_at is null and m.status in ('joined', 'invited') and c.ends_at > now() - interval '14 days' loop
    perform private.titan_cordee_settle(v_id);
    if exists (select 1 from private.titan_cordee_relays r where r.challenge_id = v_id) then perform private.titan_cordee_relay_tidy(v_id); end if;
  end loop;
  for v_id in select distinct s.from_id from private.titan_cordee_suites s
                join public.titan_challenge_members m on m.challenge_id = s.from_id and m.user_id = v_uid and m.status = 'joined'
               where s.status = 'open' loop
    perform private.titan_cordee_suite_tidy(v_id);
  end loop;
  return jsonb_build_object(
    'cordees', coalesce((
      select jsonb_agg(private.titan_cordee_state(c.id, v_uid) || jsonb_build_object('relay', private.titan_cordee_relay_state(c.id, v_uid),
                         'follows', private.titan_cordee_follows(c.id, v_uid),
                         'suite', case when c.summited_at is not null or now() > c.ends_at then private.titan_cordee_suite_state(c.id, v_uid) end,
                         'story', case when (c.summited_at is not null or now() > c.ends_at) and m.status = 'joined' then private.titan_cordee_story(c.id, v_uid) end)
                       order by (c.summited_at is null and c.ends_at > now()) desc, c.ends_at desc)
        from public.titan_challenges c join public.titan_challenge_members m on m.challenge_id = c.id and m.user_id = v_uid
       where c.kind = 'cordee' and m.status in ('joined', 'invited') and c.ends_at > now() - interval '14 days'), '[]'::jsonb),
    'titles', coalesce((select jsonb_agg(t.route order by t.route) from private.titan_cordee_titles t where t.user_id = v_uid), '[]'::jsonb));
end;
$function$;
revoke all on function public.titan_cordees_v1() from public, anon;
grant execute on function public.titan_cordees_v1() to authenticated;

-- ---------------------------------------------------------------------------------------------
-- 8. « Depuis ta dernière visite » (from 20261120120000): the cordée a new one follows, and the proposals that wait for my answer.
-- ---------------------------------------------------------------------------------------------
create or replace function public.titan_social_digest_v1(p_since timestamptz default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
set statement_timeout = '8s'
as $function$
declare
  v_uid uuid := auth.uid();
  v_since timestamptz;
  v_cordees jsonb;
  v_duo jsonb;
  v_friends integer;
  v_active28 integer;
  v_running integer;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode = '42501'; end if;
  v_since := least(now() - interval '1 hour', greatest(now() - interval '30 days', coalesce(p_since, now() - interval '7 days')));
  -- Cordées first (this settles a summit that is due), then the Duo (this closes a lapsed pairing and keeps its result).
  v_cordees := coalesce(public.titan_cordees_v1() -> 'cordees', '[]'::jsonb);
  v_duo := case when to_regprocedure('public.titan_buddy_v1()') is not null then public.titan_buddy_v1() else null end;
  select count(*)::integer into v_friends
    from public.friendships f
   where (f.user_id_1 = v_uid or f.user_id_2 = v_uid) and f.status = 'accepted'
     and private.titan_are_friends(f.user_id_1, f.user_id_2);
  select count(*)::integer into v_active28 from private.titan_effort_days(v_uid, now() - interval '28 days', now() + interval '1 minute', '-infinity'::timestamptz, 90) d where d.minutes > 0;
  select count(*)::integer into v_running from jsonb_array_elements(v_cordees) c where c->>'status' = 'active' and c->>'myStatus' = 'joined';
  return jsonb_build_object(
    'since', v_since,
    'requestsIn', (select count(*) from public.friendships f where f.user_id_2 = v_uid and f.status = 'pending'
                     and f.created_at > now() - interval '30 days' and f.created_at > v_since),
    'cheersReceived', (select count(*) from public.titan_moment_cheers c join public.titan_moments m on m.id = c.moment_id
                         where m.user_id = v_uid and c.created_at > v_since and private.titan_are_friends(v_uid, c.user_id)),
    'friendMoments', jsonb_build_object(
      'count', (select count(*) from public.titan_moments m
                 where m.user_id <> v_uid and m.visibility = 'friends' and not m.hidden and m.created_at > v_since and private.titan_are_friends(v_uid, m.user_id)),
      'latest', coalesce((select jsonb_agg(x.j order by x.at desc) from (
          select m.created_at as at, jsonb_build_object('id', m.id, 'kind', m.kind, 'title', m.title, 'at', m.created_at,
                   'author', coalesce(nullif(p.username, ''), 'Athlète')) as j
            from public.titan_moments m join public.profiles p on p.id = m.user_id
           where m.user_id <> v_uid and m.visibility = 'friends' and not m.hidden and m.created_at > v_since and private.titan_are_friends(v_uid, m.user_id)
           order by m.created_at desc limit 3) x), '[]'::jsonb)),
    -- Only friends who allow it (privacy.socialPresence) and only that they were active, never what, where or how much.
    'friendsActive', coalesce((select jsonb_agg(x.name order by x.name) from (
        select distinct coalesce(nullif(p.username, ''), 'Athlète') as name
          from public.friendships f
          join public.profiles p on p.id = case when f.user_id_1 = v_uid then f.user_id_2 else f.user_id_1 end
         where (f.user_id_1 = v_uid or f.user_id_2 = v_uid) and f.status = 'accepted' and private.titan_are_friends(v_uid, p.id)
           and not coalesce(p.is_suspended, false) and coalesce((p.privacy ->> 'socialPresence')::boolean, false)
           and exists (select 1 from private.titan_confirmed_sessions(p.id, v_since, now() + interval '1 minute', '-infinity'::timestamptz))
         limit 8) x), '[]'::jsonb),
    'cordees', coalesce((select jsonb_agg(jsonb_build_object('id', c->>'id', 'route', c->>'route', 'status', c->>'status', 'myStatus', c->>'myStatus',
                 'percent', (c->>'percent')::integer, 'camps', (c->>'camps')::integer, 'total', (c->>'total')::integer, 'target', (c->>'target')::integer,
                 'mine', (c->'me'->>'counted')::integer, 'earned', (c->>'earned')::boolean,
                 'summitedSince', c->>'status' = 'summited' and (c->>'summitedAt')::timestamptz > v_since, 'endsAt', c->>'endsAt',
                 -- V1.8.3: the finished cordée a new one follows (its route only).
                 'follows', case when jsonb_typeof(c->'follows') = 'object' then c->'follows'->>'route' end))
               from jsonb_array_elements(v_cordees) c where c->>'myStatus' in ('joined', 'invited')), '[]'::jsonb),
    -- V1.8.3: finished cordées whose group is setting off again, only when one proposal waits for my answer or I proposed one.
    'suites', coalesce((select jsonb_agg(jsonb_build_object('id', c->>'id', 'route', c->>'route',
                 'waiting', (c->'suite'->>'waiting')::integer, 'choice', (c->'suite'->>'choice')::boolean,
                 'proposals', (select coalesce(jsonb_agg(jsonb_build_object('id', p->>'id', 'route', p->>'route', 'pace', p->>'pace', 'days', (p->>'days')::integer,
                                  'status', p->>'status', 'mine', (p->>'mine')::boolean, 'by', p->'by'->>'name', 'myAnswer', p->>'myAnswer',
                                  'yes', (p->>'yes')::integer, 'eligible', (p->>'eligible')::integer, 'turn', p->'turn')), '[]'::jsonb)
                                 from jsonb_array_elements(c->'suite'->'proposals') p where p->>'status' in ('open', 'started') and jsonb_array_length(p->'turn') > 0)))
               from jsonb_array_elements(v_cordees) c
              where jsonb_typeof(c->'suite') = 'object'
                and exists (select 1 from jsonb_array_elements(c->'suite'->'proposals') p where p->>'status' in ('open', 'started') and jsonb_array_length(p->'turn') > 0)), '[]'::jsonb),
    'duo', case
      when v_duo is null then null
      when v_duo->>'status' = 'active' then jsonb_build_object('status', 'active', 'partner', v_duo->'partner'->>'name', 'together', (v_duo->>'together')::integer,
             'target', (v_duo->>'target')::integer, 'daysLeft', (v_duo->>'daysLeft')::integer)
      when v_duo->>'status' = 'pending' and v_duo->>'role' = 'invitee' then jsonb_build_object('status', 'invited', 'partner', v_duo->'partner'->>'name')
      when v_duo->'last' is not null and v_duo->'last' <> 'null'::jsonb and ((v_duo->'last'->>'endsOn')::date + 1)::timestamp at time zone 'Europe/Paris' > v_since
        then jsonb_build_object('status', 'finished', 'partner', v_duo->'last'->'partner'->>'name', 'together', (v_duo->'last'->>'together')::integer,
             'target', (v_duo->'last'->>'target')::integer, 'reached', (v_duo->'last'->>'reached')::boolean)
      else null end,
    'challengesEnded', coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'title', c.title, 'reached', r.reached) order by c.ends_at desc)
        from public.titan_challenges c
        join public.titan_challenge_members m on m.challenge_id = c.id and m.user_id = v_uid and m.status = 'joined'
        left join private.titan_challenge_results r on r.challenge_id = c.id and r.user_id = v_uid
       where c.kind = 'individual' and c.ends_at > v_since and c.ends_at <= now()), '[]'::jsonb),
    -- Shared memories: the last summits one took part in, more than a week ago.
    'memories', coalesce((select jsonb_agg(x.j order by x.at desc) from (
        select c.summited_at as at, jsonb_build_object('id', c.id, 'route', c.route, 'summitedAt', c.summited_at,
                 'members', (select count(*) from private.titan_challenge_results y where y.challenge_id = c.id)) as j
          from public.titan_challenges c join private.titan_challenge_results r on r.challenge_id = c.id and r.user_id = v_uid and r.reached
         where c.kind = 'cordee' and c.summited_at is not null and c.summited_at < now() - interval '7 days'
         order by c.summited_at desc limit 3) x), '[]'::jsonb),
    -- One suggestion, only when it can help: a pace that fits the last 28 days (never more than what was done), solo or with friends.
    'suggestion', case when v_running = 0 then jsonb_build_object('kind', 'cordee', 'activeDays28', v_active28,
        'pace', case when v_active28 >= 16 then 'soutenue' when v_active28 >= 8 then 'reguliere' else 'douce' end, 'friends', v_friends)
      else null end
  );
end;
$function$;
revoke all on function public.titan_social_digest_v1(timestamptz) from public, anon;
grant execute on function public.titan_social_digest_v1(timestamptz) to authenticated;

-- ---------------------------------------------------------------------------------------------
-- 9. The account export (cumulative): one's own proposals and answers, never another member's.
-- ---------------------------------------------------------------------------------------------
create or replace function private.titan_social_export_v1(p_uid uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'friendInvites', coalesce((select jsonb_agg(jsonb_build_object('created_at', i.created_at, 'expires_at', i.expires_at, 'revoked_at', i.revoked_at,
                       'used_at', i.used_at) order by i.created_at) from private.titan_friend_invites i where i.created_by = p_uid), '[]'::jsonb),
    'cordeeTitles', coalesce((select jsonb_agg(jsonb_build_object('route', t.route, 'challenge_id', t.challenge_id, 'earned_at', t.earned_at)
                       order by t.earned_at, t.route) from private.titan_cordee_titles t where t.user_id = p_uid), '[]'::jsonb),
    'cordeeRelays', coalesce((select jsonb_agg(x.j order by x.at) from (
        select r.opened_at as at, jsonb_build_object('challenge_id', r.challenge_id, 'step', r.step, 'action', 'transmit', 'at', r.opened_at,
               'log_id', r.opened_log, 'day', r.opened_day) as j from private.titan_cordee_relays r where r.opened_by = p_uid
        union all
        select r.confirmed_at, jsonb_build_object('challenge_id', r.challenge_id, 'step', r.step, 'action', 'confirm', 'at', r.confirmed_at,
               'log_id', r.confirmed_log, 'day', r.confirmed_day) from private.titan_cordee_relays r where r.confirmed_by = p_uid) x), '[]'::jsonb),
    'cordeeRelayTurns', coalesce((select jsonb_agg(jsonb_build_object('challenge_id', t.challenge_id, 'kind', t.kind,
        'role', case when t.kind = 'take' then 'took' when t.from_user = p_uid then 'offered' when t.accepted_by = p_uid then 'accepted' else 'offered_to_me' end,
        'open', case when t.kind = 'handover' then t.to_user is null end, 'status', t.status, 'at', t.created_at, 'expires_at', t.expires_at,
        'resolved_at', t.resolved_at) order by t.created_at)
      from private.titan_cordee_relay_turns t where t.from_user = p_uid or t.to_user = p_uid or t.accepted_by = p_uid), '[]'::jsonb),
    'cordeeSuites', coalesce((select jsonb_agg(x.j order by x.at) from (
        select s.created_at as at, jsonb_build_object('from_id', s.from_id, 'role', 'proposed', 'route', s.route, 'pace', s.pace, 'days', s.days,
               'status', s.status, 'at', s.created_at, 'started_id', s.started_id) as j
          from private.titan_cordee_suites s where s.proposed_by = p_uid
        union all
        select a.answered_at, jsonb_build_object('from_id', s.from_id, 'role', 'answered', 'answer', a.answer, 'route', s.route, 'pace', s.pace,
               'days', s.days, 'at', a.answered_at)
          from private.titan_cordee_suite_answers a join private.titan_cordee_suites s on s.id = a.suite_id
         where a.user_id = p_uid and s.proposed_by is distinct from p_uid) x), '[]'::jsonb));
$$;
revoke all on function private.titan_social_export_v1(uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- 10. The measure: groups that finished a cordée and became active together again within 14 days. Counts only.
-- ---------------------------------------------------------------------------------------------
create or replace function private.titan_cordee_suite_measure(p_since timestamptz default now() - interval '28 days')
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  with f as (
    select c.id, c.ends_at from public.titan_challenges c
     where c.kind = 'cordee' and c.ends_at >= p_since and (c.summited_at is not null or c.ends_at < now())
       and (select count(*) from public.titan_challenge_members m where m.challenge_id = c.id and m.status = 'joined') >= 2),
  s as (select s.* from private.titan_cordee_suites s join f on f.id = s.from_id),
  n as (select s.started_id as id, s.started_at, f.ends_at as from_end from s join f on f.id = s.from_id
         where s.status = 'started' and s.started_id is not null and s.started_at <= f.ends_at + interval '14 days'),
  j as (select n.id, (select count(*) from public.titan_challenge_members m where m.challenge_id = n.id and m.status = 'joined') as members,
               (private.titan_cordee_state(n.id, null)->>'contributors')::integer as contributors from n)
  select jsonb_build_object('since', p_since,
    'finishedGroups', (select count(*) from f),
    'proposals', (select count(*) from s),
    'canonicalOrChoice', (select count(*) from (select s.from_id from s group by s.from_id having count(*) >= 2) x),
    'declines', (select count(*) from private.titan_cordee_suite_answers a join s on s.id = a.suite_id where a.answer = 'no'),
    'expired', (select count(*) from s where s.status = 'expired'),
    'groupsBackWithin14Days', (select count(distinct s.from_id) from s join n on n.id = s.started_id),
    'members', coalesce((select jsonb_object_agg(x.members, x.groups) from (select j.members, count(*) as groups from j group by j.members) x), '{}'::jsonb),
    'firstParticipation', (select count(*) from j where j.contributors >= 1),
    'togetherAgain', (select count(*) from j where j.contributors >= 2));
$$;
revoke all on function private.titan_cordee_suite_measure(timestamptz) from public, anon, authenticated;
grant execute on function private.titan_cordee_suite_measure(timestamptz) to service_role;

notify pgrst, 'reload schema';
